  'villa-maria-del-triunfo': 'Villa María del Triunfo',
};
const LIMITES = { pm25: 50, pm10: 100 };
const UNIDAD = 'µg/m³';
const addDays = (s, n) => { const d = new Date(s + 'T00:00:00Z'); d.setUTCDate(d.getUTCDate() + n); return d.toISOString().slice(0, 10); };
const r1 = (x) => (x === null || x === undefined || !Number.isFinite(x)) ? null : Math.round(x * 10) / 10;
const avg = (a) => a.length ? a.reduce((s, x) => s + x, 0) / a.length : null;
const ahoraLima = () => new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 19) + '-05:00';
const nombreDe = (id) => NOMBRES[id] || id;
