// Parte 2 · paso 1: arma, por distrito, los agregados de la semana y el prompt. La IA solo ve estos números.
const filas = $input.all().map((i) => i.json).filter((f) => f && f.id);
if (!filas.length) return [];

const MIN_DIAS = 4;                       // mínimo de días con dato en la semana para redactar
const MESES = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const ini = filas[0].semana_inicio, fin = addDays(ini, 6);
const [, m1, d1] = ini.split('-').map(Number), [, m2, d2] = fin.split('-').map(Number);
const rango = m1 === m2 ? `del ${d1} al ${d2} de ${MESES[m2 - 1]}` : `del ${d1} de ${MESES[m1 - 1]} al ${d2} de ${MESES[m2 - 1]}`;
const ETQ = { pm25: 'PM2.5', pm10: 'PM10' };
const f = (x) => String(x).replace('.', ',');   // cifras con coma decimal, como se escriben en español

const porDistrito = {};
for (const f of filas) (porDistrito[f.id] = porDistrito[f.id] || []).push(f);

const SISTEMA = 'Eres el redactor del panel de analítica de calidad del aire de EcoPredict (Lima, Perú). '
  + 'Resume la semana de un distrito en 3 o 4 oraciones, en español claro para ciudadanos.'
  + '\nREGLAS OBLIGATORIAS:'
  + '\n1. Usa SOLO las cifras del bloque DATOS, tal como están escritas. No calcules, no redondees ni agregues otras cifras.'
  + '\n2. No inventes causas, fuentes de contaminación ni pronósticos.'
  + '\n3. Si el promedio diario superó el límite, aclara que es una comparación referencial con el límite de 24 horas del ECA, no un incumplimiento formal.'
  + '\n4. Si hubo pocos días con dato, dilo.'
  + '\n5. No menciones tablas, consultas ni código. No cites números de decreto ni años. Un solo párrafo, sin viñetas.'
  + '\n6. El promedio y la lectura más alta son de ESTA semana. De la semana anterior solo se conoce la variación en %, no la menciones como si fuera un promedio.'
  + '\n7. La lectura más alta es un valor puntual, NO un promedio diario: no la compares con el límite y llámala siempre "lectura más alta", nunca "máximo diario".';

const salida = [];
for (const [id, rows] of Object.entries(porDistrito)) {
  const diasMax = Math.max(...rows.map((r) => Number(r.dias)));
  if (diasMax < MIN_DIAS) continue;       // muy pocos datos: no se redacta nada

  const datos = {};
  const permitidos = new Set([0, 1, 2, 3, 4, 5, 6, 7, 24, 50, 100, d1, d2]);
  const add = (x) => { if (x !== null && Number.isFinite(x)) { permitidos.add(x); permitidos.add(Math.round(x)); } };
  for (const r of rows) {
    const prom = r1(Number(r.promedio)), max = r1(Number(r.maximo));
    const antExacto = Number(r.dias_anterior) >= MIN_DIAS ? Number(r.anterior) : null;
    let variacionPct = null, tendencia = null;
    if (antExacto !== null && antExacto !== 0) {
      // se calcula con los promedios SIN redondear, igual que el endpoint comparativo (evita 4,3 vs 4,2)
      variacionPct = r1(((Number(r.promedio) - antExacto) / antExacto) * 100);
      tendencia = Math.abs(variacionPct) < 5 ? 'estable' : (variacionPct > 0 ? 'sube' : 'baja');
    }
    // El promedio de la semana anterior NO se le da a la IA ni se permite en el texto: solo la variación.
    datos[r.parametro] = { promedio: prom, maximo: max, diasConDato: Number(r.dias), diasExcedidos: Number(r.excedidos),
                           limite: LIMITES[r.parametro], variacionPct, tendencia };
    [prom, max, variacionPct === null ? null : Math.abs(variacionPct), Number(r.dias), Number(r.excedidos)].forEach(add);
  }

  const lineas = ['pm25', 'pm10'].filter((par) => datos[par]).map((par) => [par, datos[par]]).map(([par, d]) =>
    `- ${ETQ[par]}: promedio ${f(d.promedio)} µg/m³; lectura más alta ${f(d.maximo)}; días con dato ${d.diasConDato} de 7; `
    + `días con promedio sobre el límite (${d.limite}) ${d.diasExcedidos}; `
    + (d.tendencia === null ? 'comparación con la semana anterior: sin datos suficientes'
        : `comparación con la semana anterior: variación ${f(d.variacionPct)} % (tendencia: ${d.tendencia})`));
  const usuario = `Distrito: ${nombreDe(id)}\nSemana: ${rango}\nDATOS:\n${lineas.join('\n')}\n\nRedacta el resumen.`;

  salida.push({ json: {
    id, nombre: nombreDe(id), semana_inicio: ini, semana_fin: fin, rango, datos, permitidos: [...permitidos],
    lf_inicio: new Date().toISOString(),
    groq_payload: {
      model: 'openai/gpt-oss-120b', temperature: 0.2, max_tokens: 800,
      messages: [{ role: 'system', content: SISTEMA }, { role: 'user', content: usuario }],
    },
    gemini_payload: {
      contents: [{ parts: [{ text: `${SISTEMA}\n\n${usuario}` }] }],
      generationConfig: { temperature: 0.2, maxOutputTokens: 500 },
    },
  } });
}
return salida;

