const prep = $('Preparar prompts (por distrito)').item.json;
const r = $json;

let texto = null, modelo = 'ninguno';
if (r.choices && r.choices[0]) { texto = r.choices[0].message?.content ?? null; modelo = 'groq:' + (r.model || 'desconocido'); }
else if (r.candidates && r.candidates[0]) {
  texto = (r.candidates[0].content?.parts || []).map((p) => p.text || '').join('');
  modelo = 'gemini:' + (r.modelVersion || 'desconocido');
}

const f = (x) => String(x).replace('.', ',');
const plantilla = () => {
  const frases = ['pm25', 'pm10'].filter((par) => prep.datos[par]).map((par, i) => {
    const d = prep.datos[par];
    const et = par === 'pm25' ? 'PM2.5' : 'PM10';
    const ini = i === 0
      ? `${prep.rango.charAt(0).toUpperCase() + prep.rango.slice(1)}, el ${et} de ${prep.nombre}`
      : `El ${et}`;
    let s = `${ini} tuvo un promedio de ${f(d.promedio)} µg/m³ (${d.diasConDato} días con dato) y una lectura más alta de ${f(d.maximo)} µg/m³`;
    s += d.diasExcedidos > 0
      ? `; el promedio diario superó el límite de referencia de ${d.limite} µg/m³ en ${d.diasExcedidos} ${d.diasExcedidos === 1 ? 'día' : 'días'}.`
      : `; no superó el límite de referencia de ${d.limite} µg/m³.`;
    if (d.tendencia) s += ` Frente a la semana anterior ${d.tendencia === 'estable' ? 'se mantuvo estable' : (d.tendencia === 'sube' ? 'subió' : 'bajó') + ' ' + f(Math.abs(d.variacionPct)) + ' %'}.`;
    return s;
  });
  return frases.join(' ');
};

