const ultimos = asJson(r.ultimos);
const hasta = r.hasta || null;
const dias = p.dias;
const MIN = Math.ceil(dias / 2);   // 4 de 7, 15 de 30

const desde = hasta ? addDays(hasta, -(dias - 1)) : null;
const antHasta = hasta ? addDays(hasta, -dias) : null;
