    const u = ultimos.find((x) => x.id === id);
    return { id, nombre: nombreDe(id), datosSuficientes: false, ultimoDato: u ? u.ultimo : null, parametros: null, serie: [] };
  }

  const parametros = {};
  for (const par of p.parametros) {
    const a = act.filter((f) => f.parametro === par);
    const b = ant.filter((f) => f.parametro === par);
    const prom = avg(a.map((f) => f.promedio));
    const prev = b.length >= MIN ? avg(b.map((f) => f.promedio)) : null;
